/* fdtd-2d.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* For parallelization and SIMD directives. */
#include <omp.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "fdtd-2d.h"


/* Array initialization. */
static
void init_array (int tmax,
                 int nx,
                 int ny,
                 DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
                 DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
                 DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
                 DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  int i, j;

  /* Initialize fictitious boundary values. */
  for (i = 0; i < tmax; i++)
    _fict_[i] = (DATA_TYPE) i;

  /* Initialize field arrays.
   *
   * Optimization:
   *  - Parallelize the outer loop over i with OpenMP.
   *  - Use row pointers to improve cache locality and reduce
   *    address arithmetic inside the inner loop.
   */
#pragma omp parallel for private(j) schedule(static)
  for (i = 0; i < nx; i++)
  {
    DATA_TYPE *restrict ex_row = ex[i];
    DATA_TYPE *restrict ey_row = ey[i];
    DATA_TYPE *restrict hz_row = hz[i];

    for (j = 0; j < ny; j++)
    {
      ex_row[j] = ((DATA_TYPE) i * (j + 1)) / nx;
      ey_row[j] = ((DATA_TYPE) i * (j + 2)) / ny;
      hz_row[j] = ((DATA_TYPE) i * (j + 3)) / nx;
    }
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int nx,
                 int ny,
                 DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
                 DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
                 DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("ex");
  for (i = 0; i < nx; i++)
    for (j = 0; j < ny; j++) {
      if ((i * nx + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, ex[i][j]);
    }
  POLYBENCH_DUMP_END("ex");
  POLYBENCH_DUMP_FINISH;

  POLYBENCH_DUMP_BEGIN("ey");
  for (i = 0; i < nx; i++)
    for (j = 0; j < ny; j++) {
      if ((i * nx + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, ey[i][j]);
    }
  POLYBENCH_DUMP_END("ey");

  POLYBENCH_DUMP_BEGIN("hz");
  for (i = 0; i < nx; i++)
    for (j = 0; j < ny; j++) {
      if ((i * nx + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, hz[i][j]);
    }
  POLYBENCH_DUMP_END("hz");
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_fdtd_2d [[gnu::flatten, gnu::noinline]] (int tmax,
                                                     int nx,
                                                     int ny,
                                                     DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
                                                     DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
                                                     DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
                                                     DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  /* Parameters are unused inside because PolyBench uses the _PB_*
   * versions for loop bounds. Silence potential warnings.
   */
  (void)tmax;
  (void)nx;
  (void)ny;

  int t, i, j;

  /* Precompute scalar constants once. */
  const DATA_TYPE c05 = SCALAR_VAL(0.5);
  const DATA_TYPE c07 = SCALAR_VAL(0.7);

  /* Create restrict-qualified aliases to help the compiler optimize
   * memory accesses and enable better vectorization. These aliases are
   * the only pointers used below, so the restrict contract is honored.
   */
  DATA_TYPE (*restrict ex_)[NY]   = ex;
  DATA_TYPE (*restrict ey_)[NY]   = ey;
  DATA_TYPE (*restrict hz_)[NY]   = hz;
  DATA_TYPE *restrict fict_       = _fict_;

#pragma scop

  /* Parallelize over space for each time step.
   *
   * Structure:
   *   - One OpenMP parallel region for the whole time loop to avoid
   *     repeated thread creation.
   *   - Within each time step t, we have four phases corresponding to
   *     the original loops. Each phase is an `omp for` with an implicit
   *     barrier at the end, so the dependencies between phases are
   *     preserved exactly:
   *
   *       1) ey boundary row (i = 0)
   *       2) ey interior   (i = 1..NX-1)
   *       3) ex            (i = 0..NX-1, j = 1..NY-1)
   *       4) hz            (i = 0..NX-2, j = 0..NY-2)
   *
   *   - For spatial loops, we:
   *       * parallelize the outer i-loop across threads, and
   *       * use row pointers plus `omp simd` on the inner j-loops to
   *         improve vectorization and cache use.
   */
#pragma omp parallel private(t, i, j) default(none) \
  shared(ex_, ey_, hz_, fict_)
  {
    for (t = 0; t < _PB_TMAX; t++)
    {
      const DATA_TYPE fict_t = fict_[t];

      /* 1. Update ey boundary: row i = 0. */
#pragma omp for schedule(static)
      for (j = 0; j < _PB_NY; j++)
      {
        ey_[0][j] = fict_t;
      }

      /* 2. Update ey interior: rows i = 1..NX-1.
       *    ey[i][j] -= 0.5 * (hz[i][j] - hz[i-1][j]);
       */
#pragma omp for schedule(static)
      for (i = 1; i < _PB_NX; i++)
      {
        DATA_TYPE *restrict ey_row      = ey_[i];
        DATA_TYPE *restrict hz_row      = hz_[i];
        DATA_TYPE *restrict hz_prev_row = hz_[i - 1];

#pragma omp simd
        for (j = 0; j < _PB_NY; j++)
        {
          ey_row[j] -= c05 * (hz_row[j] - hz_prev_row[j]);
        }
      }

      /* 3. Update ex: all rows i, columns j = 1..NY-1.
       *    ex[i][j] -= 0.5 * (hz[i][j] - hz[i][j-1]);
       */
#pragma omp for schedule(static)
      for (i = 0; i < _PB_NX; i++)
      {
        DATA_TYPE *restrict ex_row = ex_[i];
        DATA_TYPE *restrict hz_row = hz_[i];

#pragma omp simd
        for (j = 1; j < _PB_NY; j++)
        {
          ex_row[j] -= c05 * (hz_row[j] - hz_row[j - 1]);
        }
      }

      /* 4. Update hz: rows i = 0..NX-2, columns j = 0..NY-2.
       *    hz[i][j] -= 0.7 * (ex[i][j+1] - ex[i][j]
       *                      + ey[i+1][j] - ey[i][j]);
       */
#pragma omp for schedule(static)
      for (i = 0; i < _PB_NX - 1; i++)
      {
        DATA_TYPE *restrict hz_row   = hz_[i];
        DATA_TYPE *restrict ex_row   = ex_[i];
        DATA_TYPE *restrict ey_row   = ey_[i];
        DATA_TYPE *restrict ey_row_p = ey_[i + 1];

#pragma omp simd
        for (j = 0; j < _PB_NY - 1; j++)
        {
          hz_row[j] -= c07 * ((ex_row[j + 1] - ex_row[j]) +
                              (ey_row_p[j]   - ey_row[j]));
        }
      }

      /* Implicit barrier at the end of each omp for ensures that all
       * updates for time step t are completed before moving to t+1,
       * thus preserving the original time-stepping semantics.
       */
    } /* end for t */
  }   /* end parallel region */

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int tmax = TMAX;
  int nx = NX;
  int ny = NY;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(ex,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_2D_ARRAY_DECL(ey,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_2D_ARRAY_DECL(hz,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_1D_ARRAY_DECL(_fict_,DATA_TYPE,TMAX,tmax);

  /* Initialize array(s). */
  init_array (tmax, nx, ny,
              POLYBENCH_ARRAY(ex),
              POLYBENCH_ARRAY(ey),
              POLYBENCH_ARRAY(hz),
              POLYBENCH_ARRAY(_fict_));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_fdtd_2d (tmax, nx, ny,
                  POLYBENCH_ARRAY(ex),
                  POLYBENCH_ARRAY(ey),
                  POLYBENCH_ARRAY(hz),
                  POLYBENCH_ARRAY(_fict_));


  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(nx, ny, POLYBENCH_ARRAY(ex),
                                    POLYBENCH_ARRAY(ey),
                                    POLYBENCH_ARRAY(hz)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(ex);
  POLYBENCH_FREE_ARRAY(ey);
  POLYBENCH_FREE_ARRAY(hz);
  POLYBENCH_FREE_ARRAY(_fict_);

  return 0;
}
