  DATA_TYPE (* restrict ey_)[ny]   = ey;
  DATA_TYPE (* restrict hz_)[ny]   = hz;
  DATA_TYPE * restrict fict_       = _fict_;

  const int nx_    = _PB_NX;
  const int ny_    = _PB_NY;
  const int tmax_  = _PB_TMAX;

  /* Hoist constants out of loops. */
  const DATA_TYPE c05 = SCALAR_VAL(0.5);
  const DATA_TYPE c07 = SCALAR_VAL(0.7);

#pragma scop

  /* Parallelize across space for each time step.
     - Outer time loop remains sequential to preserve temporal
       data dependencies.
     - Within each time step, we use an OpenMP parallel region and
       four work-sharing loops, one for each original loop.
     - Each #pragma omp for has an implicit barrier at its end,
       so the order of the four stages is the same as in the
       original sequential code.
     - When compiled without -fopenmp, all OpenMP pragmas are
       ignored and the execution is identical to the baseline. */
#pragma omp parallel
  {
    for (int tt = 0; tt < tmax_; ++tt)
    {
      const DATA_TYPE ft = fict_[tt];

      /* ey[0][j] = _fict_[t];  -- boundary condition */
#pragma omp for schedule(static)
      for (int j = 0; j < ny_; ++j)
      {
        ey_[0][j] = ft;
      }

      /* Update ey for i >= 1 using hz from previous time step.
         Loops are independent in i and j, allowing parallelization
         and SIMD vectorization across j. */
#pragma omp for schedule(static)
      for (int i = 1; i < nx_; ++i)
      {
        DATA_TYPE       * restrict ey_row     = ey_[i];
        const DATA_TYPE * restrict hz_row     = hz_[i];
        const DATA_TYPE * restrict hz_prevrow = hz_[i-1];

#pragma omp simd
        for (int j = 0; j < ny_; ++j)
        {
          ey_row[j] -= c05 * (hz_row[j] - hz_prevrow[j]);
        }
      }

      /* Update ex using hz from previous time step.
         Each (i, j) is independent; we vectorize along j. */
#pragma omp for schedule(static)
      for (int i = 0; i < nx_; ++i)
      {
        DATA_TYPE       * restrict ex_row = ex_[i];
        const DATA_TYPE * restrict hz_row = hz_[i];

#pragma omp simd
        for (int j = 1; j < ny_; ++j)
        {
          ex_row[j] -= c05 * (hz_row[j] - hz_row[j-1]);
        }
      }

      /* Update hz using the newly computed ex and ey.
         Each (i, j) in the update domain (0..nx_-2, 0..ny_-2)
         is independent. We read ex and ey, write hz in-place. */
#pragma omp for schedule(static)
      for (int i = 0; i < nx_ - 1; ++i)
      {
        DATA_TYPE       * restrict hz_row     = hz_[i];
        const DATA_TYPE * restrict ex_row     = ex_[i];
        const DATA_TYPE * restrict ey_row     = ey_[i];
        const DATA_TYPE * restrict ey_nextrow = ey_[i+1];

#pragma omp simd
        for (int j = 0; j < ny_ - 1; ++j)
        {
          hz_row[j] -= c07 *
                       ((ex_row[j+1] - ex_row[j]) +
                        (ey_nextrow[j] - ey_row[j]));
        }
      }
    } /* end for tt */
  }   /* end parallel region */

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int tmax = TMAX;
  int nx = NX;
  int ny = NY;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(ex,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_2D_ARRAY_DECL(ey,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_2D_ARRAY_DECL(hz,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_1D_ARRAY_DECL(_fict_,DATA_TYPE,TMAX,tmax);

  /* Initialize array(s). */
  init_array (tmax, nx, ny,
	      POLYBENCH_ARRAY(ex),
	      POLYBENCH_ARRAY(ey),
	      POLYBENCH_ARRAY(hz),
	      POLYBENCH_ARRAY(_fict_));

