/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations:
 * - Hoist scalar constants out of loops.
 * - Improve cache locality by taking row pointers for each i.
 * - Use OpenMP to parallelize the spatial loops for each time step.
 *   We create one parallel region around the entire time loop to avoid
 *   per-iteration team setup overhead.
 * - Use 'restrict' on inner-row pointers to help the compiler
 *   vectorize the inner loops safely (ex, ey, hz are distinct arrays).
 *
 * Parallelization strategy:
 *   for each t:
 *     1) ey[0][j] boundary update         (omp for, independent in j)
 *     2) ey[i][j] for i >= 1              (omp for, independent in i,j)
 *     3) ex[i][j] for j >= 1              (omp for, independent in i,j)
 *     4) hz[i][j] using updated ex, ey    (omp for, independent in i,j)
 *
 *   Loops (1), (2), and (3) are all independent of each other in terms
 *   of data dependencies. The final loop (4) depends on the results of
 *   both (2) and (3) (and also on the boundary update (1) for ey[0][j]).
 *
 *   We therefore:
 *     - allow (1) and (2) to proceed without a barrier (nowait),
 *     - place the implicit barrier only after loop (3),
 *     - and then run loop (4).
 *
 *   This preserves the original sequential semantics while reducing
 *   synchronization overhead.
 */
static
void kernel_fdtd_2d [[gnu::flatten, gnu::noinline]] (int tmax,
		    int nx,
		    int ny,
		    DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  int t, i, j;

  /* Precompute stencil coefficients once. */
  const DATA_TYPE c0_5 = SCALAR_VAL(0.5);
  const DATA_TYPE c0_7 = SCALAR_VAL(0.7);

#pragma scop

  /* Single parallel region over the whole time loop to amortize
     OpenMP startup costs. Each thread has private loop indices. */
#pragma omp parallel private(i,j) shared(ex,ey,hz,_fict_)
  {
    for (t = 0; t < _PB_TMAX; t++)
    {
      /* 1) Boundary condition: update ey[0][*].
       *    Independent over j, no read-after-write or write-after-write
       *    between iterations. Safe to parallelize.
       */
#pragma omp for schedule(static) nowait
      for (j = 0; j < _PB_NY; j++)
        ey[0][j] = _fict_[t];

      /* 2) Update ey for i >= 1.
       *    ey[i][j] depends only on ey[i][j] and hz[i][j], hz[i-1][j]
       *    from the same time step. No inter-iteration dependency on ey.
       */
#pragma omp for schedule(static) nowait
      for (i = 1; i < _PB_NX; i++)
      {
        DATA_TYPE *restrict ey_row      = ey[i];
        DATA_TYPE *restrict hz_row      = hz[i];
        DATA_TYPE *restrict hz_prev_row = hz[i-1];

        /* Inner loop is over contiguous memory (row-major layout). */
        for (j = 0; j < _PB_NY; j++)
        {
          ey_row[j] = ey_row[j] - c0_5 * (hz_row[j] - hz_prev_row[j]);
        }
      }

      /* 3) Update ex for j >= 1.
       *    ex[i][j] depends only on ex[i][j] and hz[i][j], hz[i][j-1].
       *    No dependency on ey and no dependency among ex(i,j) updates.
       */
#pragma omp for schedule(static)
      for (i = 0; i < _PB_NX; i++)
      {
        DATA_TYPE *restrict ex_row = ex[i];
        DATA_TYPE *restrict hz_row = hz[i];

        for (j = 1; j < _PB_NY; j++)
        {
          ex_row[j] = ex_row[j] - c0_5 * (hz_row[j] - hz_row[j-1]);
        }
      }
      /* Implicit barrier here ensures:
         - loops (1), (2), and (3) for this t are all complete
         - updated ex and ey (including boundary row) are visible
           before we start updating hz. */

      /* 4) Update hz using updated ex and ey.
       *    hz[i][j] depends on hz[i][j] (old), ex[i][j], ex[i][j+1],
       *    ey[i][j], ey[i+1][j]. No dependencies on neighboring hz
       *    elements, so the (i,j) iterations are independent.
       */
#pragma omp for schedule(static)
      for (i = 0; i < _PB_NX - 1; i++)
      {
        DATA_TYPE *restrict hz_row       = hz[i];
        DATA_TYPE *restrict ex_row       = ex[i];
        DATA_TYPE *restrict ey_row       = ey[i];
        DATA_TYPE *restrict ey_next_row  = ey[i+1];

        for (j = 0; j < _PB_NY - 1; j++)
        {
          hz_row[j] = hz_row[j]
                    - c0_7 * ( (ex_row[j+1]   - ex_row[j]) +
                               (ey_next_row[j] - ey_row[j]) );
        }
      }

      /* Implicit barrier here (end of omp for) ensures all hz updates
         for this t are complete before the next time step starts. */
    }
  }

#pragma endscop
}


